package io.mavsdk.kotlin.plugins.mission_raw

import io.mavsdk.kotlin.System
import kotlin.coroutines.resume
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow
import kotlinx.coroutines.suspendCancellableCoroutine

/** Enable raw missions as exposed by MAVLink. */
class MissionRaw internal constructor(private val native: MissionRawNative) : AutoCloseable {
    private var closed = false

    /** Possible results returned for action requests. */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request succeeded */
        SUCCESS(1),
        /** Error */
        ERROR(2),
        /** Too many mission items in the mission */
        TOO_MANY_MISSION_ITEMS(3),
        /** Vehicle is busy */
        BUSY(4),
        /** Request timed out */
        TIMEOUT(5),
        /** Invalid argument */
        INVALID_ARGUMENT(6),
        /** Mission downloaded from the system is not supported */
        UNSUPPORTED(7),
        /** No mission available on the system */
        NO_MISSION_AVAILABLE(8),
        /** Mission transfer (upload or download) has been cancelled */
        TRANSFER_CANCELLED(9),
        /** Failed to open the QGroundControl plan */
        FAILED_TO_OPEN_QGC_PLAN(10),
        /** Failed to parse the QGroundControl plan */
        FAILED_TO_PARSE_QGC_PLAN(11),
        /** No system connected */
        NO_SYSTEM(12),
        /** Request denied */
        DENIED(13),
        /** Mission type is not consistent */
        MISSION_TYPE_NOT_CONSISTENT(14),
        /** The mission item sequences are not increasing correctly */
        INVALID_SEQUENCE(15),
        /** The current item is not set correctly */
        CURRENT_INVALID(16),
        /** There was a protocol error */
        PROTOCOL_ERROR(17),
        /** The system does not support the MISSION_INT protocol */
        INT_MESSAGES_NOT_SUPPORTED(18),
        /** Failed to open the Mission Planner plan */
        FAILED_TO_OPEN_MISSION_PLANNER_PLAN(19),
        /** Failed to parse the Mission Planner plan */
        FAILED_TO_PARSE_MISSION_PLANNER_PLAN(20),
        /** Intermediate message showing progress */
        NEXT(21);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /**
     * Mission item exactly identical to MAVLink MISSION_ITEM_INT.
     *
     * @property seq Sequence (uint16_t)
     * @property frame The coordinate system of the waypoint (actually uint8_t)
     * @property command The scheduled action for the waypoint (actually uint16_t)
     * @property current false:0, true:1 (actually uint8_t)
     * @property autocontinue Autocontinue to next waypoint (actually uint8_t)
     * @property param1 PARAM1, see MAV_CMD enum
     * @property param2 PARAM2, see MAV_CMD enum
     * @property param3 PARAM3, see MAV_CMD enum
     * @property param4 PARAM4, see MAV_CMD enum
     * @property x PARAM5 / local: x position in meters * 1e4, global: latitude in degrees * 10^7
     * @property y PARAM6 / y position: local: x position in meters * 1e4, global: longitude in
     *   degrees *10^7
     * @property z PARAM7 / local: Z coordinate, global: altitude (relative or absolute, depending
     *   on frame)
     * @property missionType Mission type (actually uint8_t)
     */
    data class MissionItem(
        val seq: Int,
        val frame: Int,
        val command: Int,
        val current: Int,
        val autocontinue: Int,
        val param1: Float,
        val param2: Float,
        val param3: Float,
        val param4: Float,
        val x: Int,
        val y: Int,
        val z: Float,
        val missionType: Int,
    )

    /**
     * Mission plan type
     *
     * @property missionItems The mission items
     */
    data class MissionPlan(val missionItems: List<MissionItem> = emptyList())

    /**
     * Mission progress type.
     *
     * @property current Current mission item index (0-based), if equal to total, the mission is
     *   finished
     * @property total Total number of mission items
     */
    data class MissionProgress(val current: Int, val total: Int)

    /**
     * Mission import data
     *
     * @property missionItems Mission items
     * @property geofenceItems Geofence items
     * @property rallyItems Rally items
     */
    data class MissionImportData(
        val missionItems: List<MissionItem> = emptyList(),
        val geofenceItems: List<MissionItem> = emptyList(),
        val rallyItems: List<MissionItem> = emptyList(),
    )

    /**
     * Progress data coming from mission upload.
     *
     * @property progress Progress (0..1.0)
     */
    data class ProgressData(val progress: Float)

    /**
     * Upload a list of raw mission items to the system.
     *
     * The raw mission items are uploaded to a drone. Once uploaded the mission can be started and
     * executed even if the connection is lost.
     *
     * @param missionItems The mission items
     * @return The result of the request.
     */
    suspend fun uploadMission(missionItems: List<MissionItem>): Result =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = MissionRawCallbackGuard()
            native.uploadMissionAsync(missionItems) { result ->
                val parsedResult = Result.fromValue(result)
                if (
                    continuation.isActive && parsedResult != Result.NEXT && callbackGuard.tryClaim()
                ) {
                    continuation.resume(parsedResult)
                }
            }
        }

    /**
     * Upload a list of raw mission items and report upload progress.
     *
     * @param missionPlan The mission plan
     * @return The progress data
     */
    fun uploadMissionWithProgress(missionPlan: MissionPlan): Flow<kotlin.Result<ProgressData>> =
        callbackFlow {
            native.uploadMissionWithProgressAsync(missionPlan) { result, value ->
                val parsedResult = Result.fromValue(result)
                when {
                    parsedResult == Result.NEXT -> trySend(kotlin.Result.success(value))
                    parsedResult == Result.SUCCESS -> close()
                    else -> {
                        trySend(
                            kotlin.Result.failure(
                                MissionRawException(
                                    parsedResult,
                                    "uploadMissionWithProgress failed: ${parsedResult.name}",
                                )
                            )
                        )
                        close()
                    }
                }
            }
            awaitClose {}
        }

    /**
     * Upload a list of geofence items to the system.
     *
     * @param missionItems The mission items
     * @return The result of the request.
     */
    suspend fun uploadGeofence(missionItems: List<MissionItem>): Result =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = MissionRawCallbackGuard()
            native.uploadGeofenceAsync(missionItems) { result ->
                val parsedResult = Result.fromValue(result)
                if (
                    continuation.isActive && parsedResult != Result.NEXT && callbackGuard.tryClaim()
                ) {
                    continuation.resume(parsedResult)
                }
            }
        }

    /**
     * Upload a list of rally point items to the system.
     *
     * @param missionItems The mission items
     * @return The result of the request.
     */
    suspend fun uploadRallyPoints(missionItems: List<MissionItem>): Result =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = MissionRawCallbackGuard()
            native.uploadRallyPointsAsync(missionItems) { result ->
                val parsedResult = Result.fromValue(result)
                if (
                    continuation.isActive && parsedResult != Result.NEXT && callbackGuard.tryClaim()
                ) {
                    continuation.resume(parsedResult)
                }
            }
        }

    /**
     * Cancel an ongoing mission upload.
     *
     * @return The result of the request.
     */
    fun cancelMissionUpload(): Result = Result.fromValue(native.cancelMissionUpload())

    /**
     * Download a list of raw mission items from the system (asynchronous).
     *
     * @return The mission items
     */
    suspend fun downloadMission(): kotlin.Result<List<MissionItem>> =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = MissionRawCallbackGuard()
            native.downloadMissionAsync() { result, value ->
                val parsedResult = Result.fromValue(result)
                if (continuation.isActive && callbackGuard.tryClaim()) {
                    if (parsedResult == Result.SUCCESS) {
                        continuation.resume(kotlin.Result.success(value))
                    } else {
                        continuation.resume(
                            kotlin.Result.failure(
                                MissionRawException(
                                    parsedResult,
                                    "downloadMission failed: ${parsedResult.name}",
                                )
                            )
                        )
                    }
                }
            }
        }

    /**
     * Download a list of raw geofence items from the system (asynchronous).
     *
     * @return The geofence items
     */
    suspend fun downloadGeofence(): kotlin.Result<List<MissionItem>> =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = MissionRawCallbackGuard()
            native.downloadGeofenceAsync() { result, value ->
                val parsedResult = Result.fromValue(result)
                if (continuation.isActive && callbackGuard.tryClaim()) {
                    if (parsedResult == Result.SUCCESS) {
                        continuation.resume(kotlin.Result.success(value))
                    } else {
                        continuation.resume(
                            kotlin.Result.failure(
                                MissionRawException(
                                    parsedResult,
                                    "downloadGeofence failed: ${parsedResult.name}",
                                )
                            )
                        )
                    }
                }
            }
        }

    /**
     * Download a list of raw rallypoint items from the system (asynchronous).
     *
     * @return The rallypoint items
     */
    suspend fun downloadRallypoints(): kotlin.Result<List<MissionItem>> =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = MissionRawCallbackGuard()
            native.downloadRallypointsAsync() { result, value ->
                val parsedResult = Result.fromValue(result)
                if (continuation.isActive && callbackGuard.tryClaim()) {
                    if (parsedResult == Result.SUCCESS) {
                        continuation.resume(kotlin.Result.success(value))
                    } else {
                        continuation.resume(
                            kotlin.Result.failure(
                                MissionRawException(
                                    parsedResult,
                                    "downloadRallypoints failed: ${parsedResult.name}",
                                )
                            )
                        )
                    }
                }
            }
        }

    /**
     * Cancel an ongoing mission download.
     *
     * @return The result of the request.
     */
    fun cancelMissionDownload(): Result = Result.fromValue(native.cancelMissionDownload())

    /**
     * Start the mission.
     *
     * A mission must be uploaded to the vehicle before this can be called.
     *
     * @return The result of the request.
     */
    suspend fun startMission(): Result = suspendCancellableCoroutine { continuation ->
        val callbackGuard = MissionRawCallbackGuard()
        native.startMissionAsync() { result ->
            val parsedResult = Result.fromValue(result)
            if (continuation.isActive && parsedResult != Result.NEXT && callbackGuard.tryClaim()) {
                continuation.resume(parsedResult)
            }
        }
    }

    /**
     * Pause the mission.
     *
     * Pausing the mission puts the vehicle into
     * [HOLD mode](https://docs.px4.io/main/en/flight_modes_mc/hold.html). A multicopter should just
     * hover at the spot while a fixedwing vehicle should loiter around the location where it
     * paused.
     *
     * @return The result of the request.
     */
    suspend fun pauseMission(): Result = suspendCancellableCoroutine { continuation ->
        val callbackGuard = MissionRawCallbackGuard()
        native.pauseMissionAsync() { result ->
            val parsedResult = Result.fromValue(result)
            if (continuation.isActive && parsedResult != Result.NEXT && callbackGuard.tryClaim()) {
                continuation.resume(parsedResult)
            }
        }
    }

    /**
     * Clear the mission saved on the vehicle.
     *
     * @return The result of the request.
     */
    suspend fun clearMission(): Result = suspendCancellableCoroutine { continuation ->
        val callbackGuard = MissionRawCallbackGuard()
        native.clearMissionAsync() { result ->
            val parsedResult = Result.fromValue(result)
            if (continuation.isActive && parsedResult != Result.NEXT && callbackGuard.tryClaim()) {
                continuation.resume(parsedResult)
            }
        }
    }

    /**
     * Sets the raw mission item index to go to.
     *
     * By setting the current index to 0, the mission is restarted from the beginning. If it is set
     * to a specific index of a raw mission item, the mission will be set to this item.
     *
     * @param index Index of the mission item to be set as the next one (0-based)
     * @return The result of the request.
     */
    suspend fun setCurrentMissionItem(index: Int): Result =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = MissionRawCallbackGuard()
            native.setCurrentMissionItemAsync(index) { result ->
                val parsedResult = Result.fromValue(result)
                if (
                    continuation.isActive && parsedResult != Result.NEXT && callbackGuard.tryClaim()
                ) {
                    continuation.resume(parsedResult)
                }
            }
        }

    /**
     * Subscribe to mission progress updates.
     *
     * @return Mission progress
     */
    fun missionProgress(): MissionProgress = native.missionProgress()

    /**
     * Subscribe to mission progress updates.
     *
     * @return Mission progress
     */
    fun subscribeMissionProgress(): Flow<MissionProgress> = callbackFlow {
        val subscriptionHandle = native.subscribeMissionProgress() { value -> trySend(value) }
        awaitClose { native.unsubscribeMissionProgress(subscriptionHandle) }
    }

    /**
     * Subscribes to mission changed.
     *
     * This notification can be used to be informed if a ground station has been uploaded or changed
     * by a ground station or companion computer.
     *
     * @param callback Callback to notify about change.
     * @return Mission has changed
     */
    fun subscribeMissionChanged(): Flow<Boolean> = callbackFlow {
        val subscriptionHandle = native.subscribeMissionChanged() { value -> trySend(value) }
        awaitClose { native.unsubscribeMissionChanged(subscriptionHandle) }
    }

    /**
     * Import a QGroundControl missions in JSON .plan format, from a file.
     *
     * Supported:
     * - Waypoints
     * - Survey Not supported:
     * - Structure Scan
     *
     * @param qgcPlanPath File path of the QGC plan
     * @return The imported mission data
     */
    fun importQgroundcontrolMission(qgcPlanPath: String): MissionImportData =
        native.importQgroundcontrolMission(qgcPlanPath)

    /**
     * Import a QGroundControl missions in JSON .plan format, from a string.
     *
     * Supported:
     * - Waypoints
     * - Survey Not supported:
     * - Structure Scan
     *
     * @param qgcPlan QGC plan as string
     * @return The imported mission data
     */
    fun importQgroundcontrolMissionFromString(qgcPlan: String): MissionImportData =
        native.importQgroundcontrolMissionFromString(qgcPlan)

    /**
     * Import a Mission Planner mission in QGC WPL 110 format, from a file.
     *
     * Supported:
     * - Waypoints
     * - ArduPilot home position handling
     *
     * @param missionPlannerPath File path of the Mission Planner mission file
     * @return The imported mission data
     */
    fun importMissionPlannerMission(missionPlannerPath: String): MissionImportData =
        native.importMissionPlannerMission(missionPlannerPath)

    /**
     * Import a Mission Planner mission in QGC WPL 110 format, from a string.
     *
     * Supported:
     * - Waypoints
     * - ArduPilot home position handling
     *
     * @param missionPlannerMission Mission Planner mission as string
     * @return The imported mission data
     */
    fun importMissionPlannerMissionFromString(missionPlannerMission: String): MissionImportData =
        native.importMissionPlannerMissionFromString(missionPlannerMission)

    /**
     * Check if the mission is finished.
     *
     * Returns true if the mission is finished, false otherwise.
     *
     * @return True if the mission is finished, false otherwise
     */
    fun isMissionFinished(): Boolean = native.isMissionFinished()

    override fun close() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class MissionRawException(val result: Result, message: String) : Exception(message)

    companion object {
        fun create(system: System): MissionRaw =
            MissionRaw(createMissionRawNative(system.getHandle())).also {
                system.registerPlugin(it)
            }
    }
}

internal interface MissionRawNative {
    fun uploadMissionAsync(missionItems: List<MissionRaw.MissionItem>, callback: (Int) -> Unit)

    fun uploadMissionWithProgressAsync(
        missionPlan: MissionRaw.MissionPlan,
        callback: (Int, MissionRaw.ProgressData) -> Unit,
    )

    fun uploadGeofenceAsync(missionItems: List<MissionRaw.MissionItem>, callback: (Int) -> Unit)

    fun uploadRallyPointsAsync(missionItems: List<MissionRaw.MissionItem>, callback: (Int) -> Unit)

    fun cancelMissionUpload(): Int

    fun downloadMissionAsync(callback: (Int, List<MissionRaw.MissionItem>) -> Unit)

    fun downloadGeofenceAsync(callback: (Int, List<MissionRaw.MissionItem>) -> Unit)

    fun downloadRallypointsAsync(callback: (Int, List<MissionRaw.MissionItem>) -> Unit)

    fun cancelMissionDownload(): Int

    fun startMissionAsync(callback: (Int) -> Unit)

    fun pauseMissionAsync(callback: (Int) -> Unit)

    fun clearMissionAsync(callback: (Int) -> Unit)

    fun setCurrentMissionItemAsync(index: Int, callback: (Int) -> Unit)

    fun missionProgress(): MissionRaw.MissionProgress

    fun subscribeMissionProgress(callback: (MissionRaw.MissionProgress) -> Unit): Long

    fun unsubscribeMissionProgress(subscriptionHandle: Long)

    fun subscribeMissionChanged(callback: (Boolean) -> Unit): Long

    fun unsubscribeMissionChanged(subscriptionHandle: Long)

    fun importQgroundcontrolMission(qgcPlanPath: String): MissionRaw.MissionImportData

    fun importQgroundcontrolMissionFromString(qgcPlan: String): MissionRaw.MissionImportData

    fun importMissionPlannerMission(missionPlannerPath: String): MissionRaw.MissionImportData

    fun importMissionPlannerMissionFromString(
        missionPlannerMission: String
    ): MissionRaw.MissionImportData

    fun isMissionFinished(): Boolean

    fun destroy()
}

internal expect fun createMissionRawNative(systemHandle: Long): MissionRawNative

internal expect class MissionRawCallbackGuard() {
    fun tryClaim(): Boolean
}
